.live.bad{border-color:var(--accent-red);color:#e08b81}
.keybar{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:10px}
.cell{border:1px solid var(--line);border-radius:12px;background:var(--bg-panel);padding:9px 10px;min-width:0}
.cell .label{color:var(--ink-dim);font-size:10px;letter-spacing:.08em}
