.bar > i{display:block;height:100%;width:0;background:var(--accent-cyan);transition:width .2s ease}
.bar.mid > i{background:var(--accent-amber)}
.bar.bad > i{background:var(--accent-red)}
.bar.wait > i{background:#4a4a52}
.gauge{display:block;width:104px;height:60px;margin-top:4px}
.gauge .track{fill:none;stroke:var(--line);stroke-width:8;stroke-linecap:round}
.gauge .fill{fill:none;stroke:var(--accent-cyan);stroke-width:8;stroke-linecap:round;transition:stroke-dashoffset .2s ease}
.gauge.mid .fill{stroke:var(--accent-amber)}
.gauge.bad .fill{stroke:var(--accent-red)}
.gauge .gtext{fill:var(--ink);font:600 19px var(--font-mono)}
.notice{margin-top:10px;border:1px solid var(--line);border-left:3px solid var(--accent-amber);border-radius:10px;background:#141310;padding:9px 11px;font-size:12px;color:#d8cfbc}
