  function note(msg, kind) {
    var el = q('status');
    el.textContent = msg;
    el.className = 'status' + (kind ? ' ' + kind : '');
  }
  function timeout(ms) {
    return new Promise(function (_resolve, reject) {
      setTimeout(function () { reject(new Error('状态初始化超时（' + ms + 'ms）')); }, ms);
    });
  }

  // ---------- 数据读取（只读；当前楼层 + 当前 Swipe） ----------
  function readState() {
    var data = Mvu.getMvuData({ type: 'message', message_id: messageId });
    if (!data || !data.stat_data || typeof data.stat_data !== 'object' || Array.isArray(data.stat_data)) {
      throw new Error('这一楼还没有可显示的状态');
    }
    // 不检查 schema 的具体类型：不同状态提供者可能返回对象、字符串或不公开该元数据。
    return data.stat_data;
  }

  function recordKeys(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return [];
    return Object.keys(value).filter(function (key) { return key.charAt(0) !== '$'; });
  }
  function listItems(value) {
    if (!Array.isArray(value)) return [];
    return value.filter(function (item) {
      return !(item && typeof item === 'object' && item.$arrayMeta === true);
    }).map(function (item) { return String(item); });
  }

  // ---------- 通用渲染件 ----------
  function setText(id, value) { q(id).textContent = text(value); }
  function setName(id, value) {
    var el = q(id);
    var blank = isBlank(value);
    el.textContent = blank ? '未登记' : String(value);
    el.className = blank ? 'v' : 'v';
  }
  function setBadge(id, label, kind) {
    var el = q(id);
    el.textContent = label;
    el.className = 'badge' + (kind ? ' ' + kind : '');
  }
  function setChips(id, entries, emptyText) {
    var box = q(id);
    box.textContent = '';
    if (!entries.length) {
      var span = document.createElement('span');
      span.className = 'empty';
      span.textContent = emptyText || '未记录';
      box.appendChild(span);
      return;
    }
    entries.forEach(function (entry) {
      var chip = document.createElement('span');
      chip.className = 'chip';
      chip.textContent = entry;
      box.appendChild(chip);
    });
  }
  function setMeter(meterId, fillId, value, min, max, numberId, unit) {
    var v = clamp(num(value, min), min, max);
    var frac = max > min ? (v - min) / (max - min) : 0;
    var meter = q(meterId);
    var pctValue = Math.round(frac * 100);
    meter.setAttribute('aria-valuenow', String(v));
    meter.className = 'bar' + (frac <= 0.2 ? ' bad' : (frac <= 0.45 ? ' mid' : ''));
    q(fillId).style.width = pctValue + '%';
    if (numberId) q(numberId).textContent = String(v) + (unit || '');
  }
  function setGauge(gaugeId, arcId, textId, value, max, display) {
    var v = clamp(num(value, 0), 0, max);
    var frac = max > 0 ? v / max : 0;
    var gauge = q(gaugeId);
    gauge.setAttribute('aria-valuenow', String(v));
    gauge.setAttribute('class', 'gauge' + (frac >= 0.75 ? ' bad' : (frac >= 0.5 ? ' mid' : '')));
    var len = 157.08;
    var arc = q(arcId);
    arc.setAttribute('stroke-dasharray', String(len));
    arc.setAttribute('stroke-dashoffset', String(len * (1 - frac)));
    q(textId).textContent = display;
  }
  function addLine(parent, label, value) {
    var line = document.createElement('div');
    line.className = 'line';
    var b = document.createElement('b');
    b.textContent = label + '：';
    var span = document.createElement('span');
    span.textContent = text(value);
    line.appendChild(b);
    line.appendChild(span);
    parent.appendChild(line);
  }
  function emptyBlock(parent, message) {
    var d = document.createElement('div');
    d.className = 'hint';
    d.textContent = message;
    parent.appendChild(d);
  }

  // ---------- 顶栏与未登记态 ----------
  function renderKeybar(world, me, sys, registered) {
    var threat = text(world.威胁等级, '未记录');
    setText('k-threat', threat);
    var threatNote = { '平静': '暂时没有东西在找你', '不安': '附近有动静，值得先看清' , '危险': '一有响动就可能被围住', '尸潮': '成群的尸群已经在附近' };
    q('k-threat-note').textContent = threatNote[threat] || '世界状态的威胁等级';
    var stamina = clamp(num(me.身体 && me.身体.体力, 100), 0, 100);
    setMeter('k-stamina-meter', 'k-stamina-bar', stamina, 0, 100, null, null);
    q('k-stamina').textContent = String(stamina);
    var infection = me.感染 || {};
    var suspicious = infection.可疑暴露 === true || infection.是否确认 === true;
    if (suspicious) {
      var hours = clamp(num(infection.剩余小时, 36), 0, 36);
      q('k-infection').textContent = String(hours) + ' 小时';
      q('k-infection-note').textContent = infection.是否确认 === true ? '已经确认：归零就是转化' : '还没确认，但暴露过';
    } else {
      q('k-infection').textContent = '无暴露记录';
      q('k-infection-note').textContent = '当前没有可追踪的暴露';
    }
    q('k-goal').textContent = registered ? text(me.当前目标, '未记录') : '未登记／未选择';
    q('ov-registered').textContent = registered ? '已登记' : '未登记／未选择';
  }

  // ---------- 总览 ----------
  function renderOverview(world, sceneRoot, sys) {
    setText('ov-date', world.日期);
    setText('ov-phase', world.时段);
    setText('ov-place', world.地点);
    setText('ov-weather', world.天气);
    setChips('ov-present', listItems(world.在场者), '现场没有其他人在场');
    var scene = sceneRoot || {};
    setChips('ov-enemies', listItems(scene.敌对单位), '当前没有已知敌对单位');
    setChips('ov-clues', listItems(scene.可调查目标), '暂时没有可调查的目标');
    var noise = clamp(num(scene.暴露与噪音, 0), 0, 100);
    setMeter('ov-noise-meter', 'ov-noise-bar', noise, 0, 100, 'ov-noise-n', '');
    q('ov-noise-note').textContent = noise >= 60
      ? '已经到了会引东西过来的程度'
      : (noise >= 30 ? '有点响，注意别再加了' : '暂时安静');
    setText('ov-cover', scene.掩体与退路);
    setText('ov-tick', String(num(sys.时段计数, 0)));
    setText('ov-last', sys.上次后台推进);
    setText('ov-tone', sys.难度基调);
    setText('ov-note', sys.备注);
  }

  // ---------- 我 ----------
  function renderSelf(me, registered) {
    setText('me-name', registered ? me.称呼 : '未登记／未选择');
    setText('me-skill', registered ? me.专长 : '未登记');
    setText('me-origin', registered ? me.来历 : '未登记');
    setText('me-temper', registered ? me.行事倾向 : '未登记');
    setText('me-goal', registered ? me.当前目标 : '未登记／未选择');
    q('me-hint').textContent = registered ? '' : '这份内容来自你提供的主控资料；没有登记时这一栏保持空白，不会替你补写。';

    var body = me.身体 || {};
    var stamina = clamp(num(body.体力, 100), 0, 100);
    setMeter('me-stamina-meter', 'me-stamina-bar', stamina, 0, 100, 'me-stamina-n', '');
    var wound = clamp(num(body.伤势, 0), 0, 4);
    var woundLabel = ['无伤', '轻伤', '重伤', '致命伤', '已死亡'][wound] || '未记录';
    setBadge('me-wound', woundLabel, wound >= 3 ? 'bad' : (wound >= 1 ? 'warn' : 'ok'));
    var mental = clamp(num(body.精神, 100), 0, 100);
    setMeter('me-mental-meter', 'me-mental-bar', mental, 0, 100, 'me-mental-n', '');
    setText('me-dehyd', String(num(body.脱水小时, 0)));
    setText('me-hunger', String(num(body.饥饿小时, 0)));
    setText('me-awake', String(num(body.清醒小时, 0)));

    var inf = me.感染 || {};
    setBadge('me-exposed', inf.可疑暴露 === true ? '有暴露' : '无记录', inf.可疑暴露 === true ? 'warn' : 'dim');
    setBadge('me-confirmed', inf.是否确认 === true ? '已确认' : '未确认', inf.是否确认 === true ? 'bad' : 'dim');
    setText('me-reason', inf.暴露原因);
    var hours = clamp(num(inf.剩余小时, 36), 0, 36);
    setGauge('me-inf-gauge', 'me-inf-arc', 'me-inf-gtext', hours, 36, String(hours));
    q('me-inf-note').textContent = (inf.可疑暴露 === true || inf.是否确认 === true)
      ? '归零即完成转化；处置过什么看下面的记录'
      : '没有暴露记录时，这一格只是基线，不代表安全';
    setChips('me-treated', listItems(inf.已处置), '没有做过处置');

    var aw = me.觉醒 || {};
    setBadge('me-awakened', aw.是否觉醒 === true ? '已觉醒' : '未觉醒', aw.是否觉醒 === true ? 'warn' : 'dim');
    setText('me-ability', aw.是否觉醒 === true ? aw.能力类别 : '未觉醒');
    setText('me-level', aw.是否觉醒 === true ? 'Lv.' + String(num(aw.等级, 0)) : '—');
    var cost = clamp(num(aw.觉醒代价, 0), 0, 100);
    setGauge('me-cost-gauge', 'me-cost-arc', 'me-cost-gtext', cost, 100, String(cost));
    var costNote = cost >= 75 ? '高危：再用一次就可能失控' : (cost >= 50 ? '濒临失控' : (cost >= 25 ? '波动区，还在可控范围' : '稳定'));
    q('me-cost-note').textContent = aw.是否觉醒 === true ? costNote + '（数字可见，角色自己不一定知道）' : '未觉醒时这一格没有意义';
    setText('me-recover', String(num(aw.恢复小时, 0)));
    setBadge('me-expose', aw.身份是否暴露 === true ? '已暴露' : '未暴露', aw.身份是否暴露 === true ? 'bad' : 'dim');
    setText('me-risk', aw.失控风险来源);
  }

  // ---------- 物资与装备 ----------
  function supplyEntries(materials) {
    return recordKeys(materials).map(function (key) {
      return { name: key, count: num(materials[key], 0) };
    });
  }
  function renderSupply(me) {
    var materials = me.物资 || {};
    var equip = listItems(me.装备);
    var query = supplyQuery.trim();
    var mat = supplyEntries(materials).filter(function (entry) {
      return !query || entry.name.indexOf(query) >= 0;
    });
    var items = equip.filter(function (name) { return !query || name.indexOf(query) >= 0; });
    setChips('su-materials', mat.map(function (entry) {
      return entry.name + '×' + String(entry.count);
    }), query ? '没有匹配的物资' : '未记录任何物资');
    var list = q('su-equip');
    list.textContent = '';
    if (!items.length) {
      var li = document.createElement('li');
      li.textContent = query ? '没有匹配的装备' : '未记录随身装备';
      list.appendChild(li);
    } else {
      items.forEach(function (name) {
        var item = document.createElement('li');
        item.textContent = name;
        list.appendChild(item);
      });
    }
    var total = supplyEntries(materials).length + equip.length;
    var shown = mat.length + items.length;
    q('su-count').textContent = query ? ('匹配 ' + shown + ' / 共 ' + total + ' 项') : ('共 ' + total + ' 项');
  }

  // ---------- 关系 ----------
  var TRUST_BANDS = [
    { max: -50, label: '敌对', color: '#c0392b' },
    { max: -1, label: '戒备', color: '#d9a04a' },
    { max: 0, label: '陌生', color: '#6f6f78' },
    { max: 49, label: '合作', color: '#6fa8a0' },
    { max: 79, label: '信任', color: '#7fa86f' },
    { max: 100, label: '亲密', color: '#a8c98f' },
  ];
  var STANCE_COLORS = { '敌意': '#c0392b', '戒备': '#d9a04a', '中立': '#6f6f78', '合作': '#6fa8a0', '同盟': '#7fa86f' };

  function trustBand(value) {
    var v = clamp(num(value, 0), -100, 100);
    for (var i = 0; i < TRUST_BANDS.length; i += 1) {
      if (v <= TRUST_BANDS[i].max) return TRUST_BANDS[i];
    }
    return TRUST_BANDS[TRUST_BANDS.length - 1];
  }
  function svgEl(name, attrs) {
    var el = document.createElementNS(SVGNS, name);
    Object.keys(attrs || {}).forEach(function (key) { el.setAttribute(key, String(attrs[key])); });
    return el;
  }
  function drawGraph(companions, factions) {
    var svg = q('re-graph');
    svg.textContent = '';
    var names = Object.keys(companions).concat(Object.keys(factions));
    svg.setAttribute('aria-label', '关系图：中心是你，周围是 ' + Object.keys(companions).length + ' 名同伴与 ' + Object.keys(factions).length + ' 个势力；下方列表给出同样的内容');
    if (!names.length) {
      q('re-graphbox').hidden = true;
      return;
    }
    q('re-graphbox').hidden = false;
    var cx = 170;
    var cy = 110;
    var edge = svgEl('circle', { cx: cx, cy: cy, r: 4, fill: '#c0392b' });
    svg.appendChild(svgEl('circle', { cx: cx, cy: cy, r: 22, fill: 'none', stroke: '#c0392b', 'stroke-width': 1.5 }));
    svg.appendChild(edge);
    var center = svgEl('text', { x: cx, y: cy + 38, fill: '#e8e6e2', 'font-size': 12, 'text-anchor': 'middle' });
    center.textContent = '你';
    svg.appendChild(center);
    var compNames = Object.keys(companions);
    var facNames = Object.keys(factions);
    function place(count, index, top) {
      var span = count > 1 ? index / (count - 1) : 0.5;
      var angle = top ? (Math.PI * 1.12 - span * Math.PI * 0.24 - Math.PI * 0.5) : (Math.PI * 0.5 + span * Math.PI * 0.52);
      var rx = 132;
      var ry = top ? 74 : 78;
      return { x: cx + Math.cos(angle) * rx, y: cy + Math.sin(angle) * ry };
    }
    compNames.forEach(function (name, index) {
      var data = companions[name] || {};
      var pos = place(compNames.length, index, true);
      var band = trustBand(data.好感度);
      svg.appendChild(svgEl('line', { x1: cx, y1: cy, x2: pos.x, y2: pos.y, stroke: band.color, 'stroke-width': 2, opacity: 0.85 }));
      svg.appendChild(svgEl('circle', { cx: pos.x, cy: pos.y, r: 13, fill: '#17171c', stroke: band.color, 'stroke-width': 2 }));
      var label = svgEl('text', { x: pos.x, y: pos.y + 4, fill: '#e8e6e2', 'font-size': 10, 'text-anchor': 'middle' });
      label.textContent = name.slice(0, 3);
      svg.appendChild(label);
      var sub = svgEl('text', { x: pos.x, y: pos.y + 26, fill: '#9a978f', 'font-size': 9, 'text-anchor': 'middle' });
      sub.textContent = band.label + ' ' + String(clamp(num(data.好感度, 0), -100, 100));
      svg.appendChild(sub);
    });
    facNames.forEach(function (name, index) {
      var data = factions[name] || {};
      var pos = place(facNames.length, index, false);
      var color = STANCE_COLORS[data.立场] || '#6f6f78';
      svg.appendChild(svgEl('line', { x1: cx, y1: cy, x2: pos.x, y2: pos.y, stroke: color, 'stroke-width': 2, 'stroke-dasharray': '5 4', opacity: 0.85 }));
      svg.appendChild(svgEl('rect', { x: pos.x - 12, y: pos.y - 12, width: 24, height: 24, rx: 5, fill: '#17171c', stroke: color, 'stroke-width': 2 }));
      var label = svgEl('text', { x: pos.x, y: pos.y + 4, fill: '#e8e6e2', 'font-size': 10, 'text-anchor': 'middle' });
      label.textContent = name.slice(0, 3);
      svg.appendChild(label);
      var sub = svgEl('text', { x: pos.x, y: pos.y + 26, fill: '#9a978f', 'font-size': 9, 'text-anchor': 'middle' });
      sub.textContent = text(data.立场, '中立');
      svg.appendChild(sub);
    });
  }
  function renderLegend() {
    var box = q('re-legend');
    box.textContent = '';
    TRUST_BANDS.forEach(function (band) {
      var item = document.createElement('span');
      item.className = 'item';
      var dot = document.createElement('i');
      dot.className = 'dot';
      dot.style.background = band.color;
      var label = document.createElement('span');
      label.textContent = '同伴·' + band.label;
      item.appendChild(dot);
      item.appendChild(label);
      box.appendChild(item);
    });
    Object.keys(STANCE_COLORS).forEach(function (stance) {
      var item = document.createElement('span');
      item.className = 'item';
      var dot = document.createElement('i');
      dot.className = 'dot';
      dot.style.background = STANCE_COLORS[stance];
      dot.style.borderRadius = '3px';
      var label = document.createElement('span');
      label.textContent = '势力·' + stance;
      item.appendChild(dot);
      item.appendChild(label);
      box.appendChild(item);
    });
  }
  function renderRelation(companions, factions) {
    drawGraph(companions, factions);
    renderLegend();
    var compBox = q('re-companions');
    compBox.textContent = '';
    var compNames = Object.keys(companions);
    if (!compNames.length) {
      emptyBlock(compBox, '还没有认识的人；先接触谁，谁才会出现在这里。');
    } else {
      compNames.forEach(function (name) {
        var data = companions[name] || {};
        var card = document.createElement('div');
        card.className = 'card';
        var top = document.createElement('div');
        top.className = 'top';
        var who = document.createElement('span');
        who.className = 'who';
        who.textContent = name;
        var meta = document.createElement('span');
        meta.className = 'meta';
        var band = trustBand(data.好感度);
        meta.textContent = text(data.类型, 'NPC') + ' · ' + band.label + '（' + String(clamp(num(data.好感度, 0), -100, 100)) + '）' + (data.是否在场 === true ? ' · 在场' : ' · 不在场');
        top.appendChild(who);
        top.appendChild(meta);
        card.appendChild(top);
        addLine(card, '当前地点', data.当前地点);
        addLine(card, '当前行动', data.当前行动);
        addLine(card, '关系依据', (isBlank(data.关系依据) ? '还没有可指认的互动' : data.关系依据));
        addLine(card, '亏欠', data.亏欠);
        addLine(card, '状态', data.状态);
        compBox.appendChild(card);
      });
    }
    var facBox = q('re-factions');
    facBox.textContent = '';
    var facNames = Object.keys(factions);
    if (!facNames.length) {
      emptyBlock(facBox, '还没有和任何势力打过交道。');
    } else {
      facNames.forEach(function (name) {
        var data = factions[name] || {};
        var card = document.createElement('div');
        card.className = 'card';
        var top = document.createElement('div');
        top.className = 'top';
        var who = document.createElement('span');
        who.className = 'who';
        who.textContent = name;
        var meta = document.createElement('span');
        meta.className = 'meta';
        meta.textContent = '立场：' + text(data.立场, '中立');
        top.appendChild(who);
        top.appendChild(meta);
        card.appendChild(top);
        var attention = clamp(num(data.关注度, 0), 0, 100);
        var line = document.createElement('div');
        line.className = 'meterline';
        var kh = document.createElement('span');
        kh.className = 'k';
        kh.textContent = '关注度';
        var bar = document.createElement('div');
        bar.className = 'bar';
        bar.setAttribute('role', 'progressbar');
        bar.setAttribute('aria-label', name + ' 的关注度');
        bar.setAttribute('aria-valuemin', '0');
        bar.setAttribute('aria-valuemax', '100');
        bar.setAttribute('aria-valuenow', String(attention));
        var fill = document.createElement('i');
        fill.style.width = attention + '%';
        fill.style.background = STANCE_COLORS[data.立场] || '#6f6f78';
        bar.appendChild(fill);
        var n = document.createElement('span');
        n.className = 'n';
        n.textContent = String(attention);
        line.appendChild(kh);
        line.appendChild(bar);
        line.appendChild(n);
        card.appendChild(line);
        var progress = clamp(num(data.后台进度, 0), 0, 100);
        var line2 = document.createElement('div');
        line2.className = 'meterline';
        var kh2 = document.createElement('span');
        kh2.className = 'k';
        kh2.textContent = '后台进度';
        var bar2 = document.createElement('div');
        bar2.className = 'bar';
        bar2.setAttribute('role', 'progressbar');
        bar2.setAttribute('aria-label', name + ' 的后台进度');
        bar2.setAttribute('aria-valuemin', '0');
        bar2.setAttribute('aria-valuemax', '100');
        bar2.setAttribute('aria-valuenow', String(progress));
        var fill2 = document.createElement('i');
        fill2.style.width = progress + '%';
        fill2.style.background = '#d9a04a';
        bar2.appendChild(fill2);
        var n2 = document.createElement('span');
        n2.className = 'n';
        n2.textContent = String(progress);
        line2.appendChild(kh2);
        line2.appendChild(bar2);
        line2.appendChild(n2);
        card.appendChild(line2);
        addLine(card, '当前阶段', data.当前阶段);
        addLine(card, '下一步', data.下一步);
        addLine(card, '已知我方信息', data.已知我方信息);
        facBox.appendChild(card);
      });
    }
  }

  // ---------- 据点 ----------
  var ATTITUDE_STOPS = ['排斥', '观望', '接纳', '依赖'];
  function drawAttitudeAxis(card, label, attitude) {
    var index = ATTITUDE_STOPS.indexOf(attitude);
    if (index < 0) index = 1;
    var bar = document.createElement('div');
    bar.className = 'meterline';
    var k = document.createElement('span');
    k.className = 'k';
    k.textContent = label;
    var svg = svgEl('svg', { viewBox: '0 0 240 26', width: '100%', height: '26', 'aria-hidden': 'true', focusable: 'false' });
    var x0 = 14;
    var x1 = 226;
    svg.appendChild(svgEl('line', { x1: x0, y1: 13, x2: x1, y2: 13, stroke: '#2a2a31', 'stroke-width': 3 }));
    var markerX = x0 + ((x1 - x0) * index) / (ATTITUDE_STOPS.length - 1);
    svg.appendChild(svgEl('line', { x1: markerX, y1: 5, x2: markerX, y2: 21, stroke: '#d9a04a', 'stroke-width': 3 }));
    ATTITUDE_STOPS.forEach(function (name, i) {
      var x = x0 + ((x1 - x0) * i) / (ATTITUDE_STOPS.length - 1);
      svg.appendChild(svgEl('circle', { cx: x, cy: 13, r: 2.5, fill: '#6f6f78' }));
      var t = svgEl('text', { x: x, y: 9, fill: '#9a978f', 'font-size': 8, 'text-anchor': 'middle' });
      t.textContent = name;
      svg.appendChild(t);
    });
    var n = document.createElement('span');
    n.className = 'n';
    n.textContent = text(attitude, '观望');
    bar.appendChild(k);
    bar.appendChild(svg);
    bar.appendChild(n);
    card.appendChild(bar);
  }
  function renderHoldouts(holdouts) {
    var box = q('ho-list');
    box.textContent = '';
    var names = Object.keys(holdouts);
    if (!names.length) {
      emptyBlock(box, '还没有进入或接触过任何据点。');
      return;
    }
    names.forEach(function (name) {
      var data = holdouts[name] || {};
      var card = document.createElement('div');
      card.className = 'card';
      var top = document.createElement('div');
      top.className = 'top';
      var who = document.createElement('span');
      who.className = 'who';
      who.textContent = name;
      var meta = document.createElement('span');
      meta.className = 'meta';
      meta.textContent = '控制方：' + text(data.控制方, '待初始化') + ' · 人数：' + String(num(data.人数, 0));
      top.appendChild(who);
      top.appendChild(meta);
      card.appendChild(top);
      var morale = clamp(num(data.士气, 50), 0, 100);
      var line = document.createElement('div');
      line.className = 'meterline';
      var k = document.createElement('span');
      k.className = 'k';
      k.textContent = '士气';
      var bar = document.createElement('div');
      bar.className = 'bar';
      bar.setAttribute('role', 'progressbar');
      bar.setAttribute('aria-label', name + ' 的士气');
      bar.setAttribute('aria-valuemin', '0');
      bar.setAttribute('aria-valuemax', '100');
      bar.setAttribute('aria-valuenow', String(morale));
      var fill = document.createElement('i');
      fill.style.width = morale + '%';
      bar.appendChild(fill);
      var n = document.createElement('span');
      n.className = 'n';
      n.textContent = String(morale);
      line.appendChild(k);
      line.appendChild(bar);
      line.appendChild(n);
      card.appendChild(line);
      drawAttitudeAxis(card, '对我态度', data.对我态度);
      addLine(card, '配给', data.配给);
      addLine(card, '防御', data.防御);
      var mats = recordKeys(data.物资);
      var row = document.createElement('div');
      row.className = 'line';
      var b = document.createElement('b');
      b.textContent = '库存：';
      row.appendChild(b);
      var chips = document.createElement('span');
      chips.className = 'chips';
      if (!mats.length) {
        var empty = document.createElement('span');
        empty.className = 'empty';
        empty.textContent = '未记录';
        chips.appendChild(empty);
      } else {
        mats.forEach(function (key) {
          var chip = document.createElement('span');
          chip.className = 'chip';
          chip.textContent = key + '×' + String(num(data.物资[key], 0));
          chips.appendChild(chip);
        });
      }
      row.appendChild(chips);
      card.appendChild(row);
      box.appendChild(card);
    });
  }

  // ---------- 悬念与线索 ----------
  function renderThreads(threads) {
    var box = q('th-list');
    box.textContent = '';
    var names = Object.keys(threads);
    if (!names.length) {
      emptyBlock(box, '目前没有挂着的悬念；遇到线索时它们会出现在这里。');
      return;
    }
    names.forEach(function (name) {
      var data = threads[name] || {};
      var card = document.createElement('div');
      card.className = 'card';
      var top = document.createElement('div');
      top.className = 'top';
      var who = document.createElement('span');
      who.className = 'who';
      who.textContent = name;
      var cred = text(data.可信度, '未经核实');
      var badge = document.createElement('span');
      badge.className = 'badge' + (cred === '已核实' ? ' ok' : (cred === '传闻' || cred === '存疑' ? ' warn' : ' dim'));
      badge.textContent = cred;
      var done = document.createElement('span');
      done.className = 'badge' + (data.是否收束 === true ? ' dim' : ' warn');
      done.textContent = data.是否收束 === true ? '已收束' : '未收束';
      top.appendChild(who);
      top.appendChild(badge);
      top.appendChild(done);
      card.appendChild(top);
      addLine(card, '涉及方', data.涉及方);
      addLine(card, '最后进展', data.最后进展);
      box.appendChild(card);
    });
  }

  // ---------- 主渲染 ----------
  function render(data) {
    state = data;
    var world = data.世界 || {};
    var me = data.主控 || {};
    var sys = data.系统 || {};
    var registered = sys.已登记 === true && !isBlank(me.称呼) && me.称呼 !== '待登记';
    q('pending').hidden = registered;
    renderKeybar(world, me, sys, registered);
    renderOverview(world, data.现场 || {}, sys);
    renderSelf(me, registered);
    renderSupply(me);
    renderRelation(data.同伴 || {}, data.势力 || {});
    renderHoldouts(data.据点 || {});
    renderThreads(data.悬念 || {});
    q('identity').textContent = '正在显示当前消息的状态';
    q('live').textContent = '已同步';
    q('live').className = 'live ok';
  }

  async function refresh() {
    try {
      if (typeof getChatMessages === 'function') {
        var floor = getChatMessages(messageId, { include_swipes: true })[0];
        swipeId = floor ? Number(floor.swipe_id || 0) : 0;
      } else {
        swipeId = 0;
      }
      render(readState());
      note('状态已同步。消息被编辑或切换版本后会重新读取。', 'ok');
      q('problem').hidden = true;
    } catch (error) {
      q('live').textContent = '不可用';
      q('live').className = 'live bad';
      console.error('[我，非我状态栏] 读取失败', error);
      q('problem-text').textContent = '这条消息暂时没有可显示的状态。可以稍后重新读取；开场或尚未结算的消息没有状态是正常的。';
      q('problem').hidden = false;
      note('读取失败：' + (error && error.message ? error.message : String(error)), 'error');
    }
  }

  // ---------- 分区切换（标准 tablist 键盘行为） ----------
  function setupTabs() {
    var tabs = Array.prototype.slice.call(document.querySelectorAll('.tab'));
    function select(index, focus) {
      tabs.forEach(function (tab, i) {
        var on = i === index;
        tab.setAttribute('aria-selected', on ? 'true' : 'false');
        tab.tabIndex = on ? 0 : -1;
        var panel = q(tab.getAttribute('aria-controls'));
        if (panel) panel.hidden = !on;
      });
      if (focus) tabs[index].focus();
    }
    tabs.forEach(function (tab, index) {
      tab.addEventListener('click', function () { select(index, false); });
      tab.addEventListener('keydown', function (event) {
        var next = null;
        if (event.key === 'ArrowRight') next = (index + 1) % tabs.length;
        else if (event.key === 'ArrowLeft') next = (index - 1 + tabs.length) % tabs.length;
        else if (event.key === 'Home') next = 0;
        else if (event.key === 'End') next = tabs.length - 1;
        if (next === null) return;
        event.preventDefault();
        select(next, true);
      });
    });
  }

  // ---------- 事件与生命周期 ----------
  function bindEvents() {
    if (typeof eventOn !== 'function') return;
    if (typeof tavern_events === 'object' && tavern_events) {
      [tavern_events.MESSAGE_UPDATED, tavern_events.MESSAGE_SWIPED].forEach(function (name) {
        if (!name) return;
        stops.push(eventOn(name, function (id) {
          if (Number(id) === messageId) refresh();
        }));
      });
      if (tavern_events.MESSAGE_DELETED) {
        stops.push(eventOn(tavern_events.MESSAGE_DELETED, function () { /* 楼层被删除时不做动作，等待宿主重建 */ }));
      }
    }
  }
  addEventListener('pagehide', function () {
    stops.forEach(function (stop) {
      if (stop && typeof stop.stop === 'function') stop.stop();
    });
    stops = [];
  }, { once: true });

  q('retry').addEventListener('click', function () { refresh(); });
  q('su-search').addEventListener('input', function (event) {
    var value = event.target.value || '';
    if (searchTimer) clearTimeout(searchTimer);
    searchTimer = setTimeout(function () {
      supplyQuery = value;
      if (state) renderSupply(state.主控 || {});
    }, 200);
  });

  (async function boot() {
    try {
      if (typeof getCurrentMessageId !== 'function') throw new Error('当前消息暂时无法读取状态');
      if (typeof Mvu === 'undefined' && typeof waitGlobalInitialized !== 'function') throw new Error('状态读取尚未就绪');
      messageId = Number(getCurrentMessageId());
      if (!Number.isInteger(messageId) || messageId < 0) throw new Error('无法取得这一楼的编号');
      setupTabs();
      if (typeof waitGlobalInitialized === 'function') {
        await Promise.race([waitGlobalInitialized('Mvu'), timeout(8000)]);
      }
      bindEvents();
      await refresh();
    } catch (error) {
      q('live').textContent = '无法启动';
      q('live').className = 'live bad';
      console.error('[我，非我状态栏] 启动失败', error);
      q('problem-text').textContent = '状态面板暂时无法启动。请重新读取，或稍后再试。';
      q('problem').hidden = false;
      note('状态面板暂时不可用。', 'error');
    }
  })();
})();
</script>
