      <p class="subhead">复制之后怎么做</p>
      <div class="notice">
        <h4>交接五步</h4>
        <ol>
          <li>点「复制资料块」，把这段文字拿到手。</li>
          <li>如果你想让它在整局里都生效：把这份资料保存到你使用的主控资料中。（也可以跳过这一步。）</li>
          <li>回到聊天，把第 0 楼<b>向右滑动</b>，选你刚才挑的那条开场。</li>
          <li>把复制的资料块<b>亲手发送</b>出去——它是你的第一条消息，不是系统替你发的。</li>
          <li>下一次回复之后，如果状态栏里的主控一栏还是「待登记」，<b>不要手动补写剧情状态</b>：保留你的资料消息，重新生成一次回复就行。</li>
        </ol>
      </div>
      <div class="notice">
        <h4>不登记也能开始</h4>
        你也可以什么都不填，直接滑到你想要的那条开场开始玩。世界在你自我介绍之前不会替你安排身份；等你需要的时候再回来登记，也来得及。
      </div>
      <div class="notice red">
        <h4>这一页不会做的事</h4>
        <ul>
          <li>不替你保存主控资料，不替你修改聊天内容，也不替你发送消息。</li>
          <li>不替你切换开场、不替你发消息、不碰你的输入框。</li>
          <li>不读写状态栏里的数据，也不进剧情——它只是一张登记用的纸。</li>
          <li>「复制成功」不等于「资料已经生效」：真正生效要靠你亲手发出资料，或保存到你自己的主控资料中。</li>
        </ul>
      </div>

      <div class="step-nav">
        <button type="button" class="btn ghost" data-goto="8">← 上一步</button>
        <span class="pos">FINAL / 10</span>
        <span style="flex:1 1 auto"></span>
        <button type="button" class="btn primary copy-trigger">复制资料块</button>
      </div>
    </section>

  </main>

  <aside class="preview" id="previewPanel">
    <div class="preview-head">
      <span class="preview-title">资料块预览</span>
      <span class="preview-state" id="previewState" aria-live="polite">跟着表单实时生成</span>
    </div>
    <textarea id="preview" spellcheck="false" aria-label="资料块预览，可以直接修改"></textarea>
    <div class="preview-actions">
      <button type="button" class="btn" id="btn-refresh">刷新预览</button>
      <button type="button" class="btn primary copy-trigger">复制资料块</button>
    </div>
    <p class="preview-note">这段文字是你要交出去的全部内容：只有你写的东西，没有替你补的部分。世界核心、NPC 设定和其他主控的资料都不在这里面。</p>
  </aside>
</div>

<button type="button" class="preview-toggle" id="btn-preview-toggle" aria-expanded="false" aria-controls="previewPanel">资料块预览</button>
<div class="toast" id="toast" role="status"></div>
<p class="foot">《我，非我》· 幸存者登记档案 —— 这一页只在开始之前出现一次。世界不会因为你在读它就等你。</p>

<script>
(function () {
  'use strict';

  var TOTAL = 10;
  var BLOCK_TITLE = '【我，非我·主控资料】';
  var BLOCK_TITLE_AMEND = '【我，非我·主控资料更正】';
  var FOOTER = '以上只代表本份主控资料，不改变世界核心、NPC 基础设定或其他主控资料。未填写内容保持未设定；请不要替我补写过去、关系、台词或下一步行动。';
  var AWAKEN_IDS = ['f-awaken-path', 'f-ability-type', 'f-ability-level', 'f-ability-manifest', 'f-awaken-cost', 'f-backlash', 'f-expose'];

  var GROUPS = [
    ['基础身份', [['称呼', 'f-name'], ['年龄', 'f-age'], ['性别', 'f-gender'], ['国籍/民族', 'f-nationality'], ['末日前职业', 'f-occupation'], ['角色定位', 'f-template']]],
    ['生存背景', [['爆发时所在地区', 'f-location'], ['当前所处环境', 'f-environment'], ['生存经历', 'f-survival'], ['身体状况', 'f-health'], ['精神状态', 'f-mental']]],
    ['阵营归属', [['所属势力', 'f-faction'], ['与势力关系', 'f-faction-relation'], ['对其他势力态度', 'f-faction-attitude']]],
    ['觉醒设定', [['觉醒状态', 'f-awakened'], ['觉醒路径', 'f-awaken-path'], ['能力类别', 'f-ability-type'], ['能力等级', 'f-ability-level'], ['能力表现', 'f-ability-manifest'], ['觉醒代价', 'f-awaken-cost'], ['反噬表现', 'f-backlash'], ['身份是否公开', 'f-expose']]],
    ['性格与信念', [['道德光谱', 'f-moral'], ['主要性格', 'f-personality1'], ['次要性格', 'f-personality2'], ['显著癖好', 'f-habit'], ['个人信条', 'f-creed'], ['首要目标', 'f-goal1'], ['次要目标', 'f-goal2']]],
    ['装备与外观', [['主要武器', 'f-weapon1'], ['副武器', 'f-weapon2'], ['防护装备', 'f-armor'], ['随身物品', 'f-item'], ['随身消耗品', 'f-item-note'], ['外貌描述', 'f-appearance'], ['显著特征', 'f-feature'], ['称号或绰号', 'f-title']]],
    ['补充设定', [['背景故事', 'f-backstory'], ['重要关系人', 'f-relation'], ['角色秘密', 'f-secret'], ['最恐惧的事', 'f-fear'], ['特殊技能', 'f-skill'], ['附加备注', 'f-notes']]],
    ['开局与交接', [['出场路线', 'f-route'], ['已经认识的人或势力', 'f-known'], ['本次来意', 'f-intent']]]
  ];

  var byId = function (id) { return document.getElementById(id); };
  var preview = byId('preview');
  var previewState = byId('previewState');
  var toastEl = byId('toast');
  var toastTimer = null;
  var manualEdit = false;

  function toast(message, kind) {
    toastEl.textContent = message;
    toastEl.className = 'toast show' + (kind ? ' ' + kind : '');
    if (toastTimer) { clearTimeout(toastTimer); }
    toastTimer = setTimeout(function () { toastEl.className = 'toast' + (kind ? ' ' + kind : ''); }, 3200);
  }

  function radioValue(name) {
    var list = document.getElementsByName(name);
    for (var i = 0; i < list.length; i += 1) {
      if (list[i].checked) { return list[i].value; }
    }
    return '';
  }

  function textValue(id) {
    var el = byId(id);
    if (!el) { return ''; }
    return String(el.value || '').trim();
  }

  function value(id) {
    var el = byId(id);
    if (!el) { return ''; }
    if (el.tagName === 'SELECT') {
      if (el.value === '__custom__') {
        var custom = byId(id + '-custom');
        return custom ? String(custom.value || '').trim() : '';
      }
      return el.value;
    }
    if (el.type === 'checkbox') { return el.checked ? '是' : ''; }
    return String(el.value || '').trim();
  }

  function routeName() {
    var list = document.getElementsByName('f-route');
    for (var i = 0; i < list.length; i += 1) {
      if (list[i].checked) { return list[i].getAttribute('data-name') || list[i].value; }
    }
    return '';
  }

  function pushIfFilled(body, label, id, awakened) {
    if (AWAKEN_IDS.indexOf(id) >= 0 && awakened !== '已觉醒') { return; }
    if (id === 'f-awakened') {
      body.push([label, awakened || '未觉醒']);
      return;
    }
    if (id === 'f-route') {
      var pick = routeName();
      if (pick) { body.push([label, pick]); }
      return;
    }
    if (id === 'f-faction' || id === 'f-moral') {
      var chosen = radioValue(id);
      if (chosen === '__custom__') {
        var customText = textValue(id + '-custom');
        if (customText) { body.push([label, customText]); }
        return;
      }
      if (id === 'f-faction' && chosen === '无所属（独行者）') { return; }
      if (chosen) { body.push([label, chosen]); }
      return;
    }
    var text = value(id);
    if (text) { body.push([label, text]); }
  }

  function buildBlock() {
    var amended = byId('f-amend');
    var lines = [amended && amended.checked ? BLOCK_TITLE_AMEND : BLOCK_TITLE];
    var awakened = radioValue('f-awakened');
    var filled = 0;
    for (var g = 0; g < GROUPS.length; g += 1) {
      var fields = GROUPS[g][1];
      var body = [];
      for (var f = 0; f < fields.length; f += 1) {
        pushIfFilled(body, fields[f][0], fields[f][1], awakened);
      }
      if (body.length === 0) { continue; }
      lines.push('');
      lines.push('〔' + GROUPS[g][0] + '〕');
      for (var b = 0; b < body.length; b += 1) {
        lines.push(body[b][0] + '：' + body[b][1]);
        filled += 1;
      }
    }
    lines.push('');
    lines.push(FOOTER);
    return { text: lines.join('\n'), filled: filled };
  }

  function refreshPreview(fromFields) {
    var built = buildBlock();
    preview.value = built.text;
    manualEdit = false;
    previewState.textContent = (fromFields ? '已同步 · ' : '') + '填了 ' + built.filled + ' 项';
  }

  function showStep(index) {
    if (index < 0 || index >= TOTAL) { return; }
    for (var i = 0; i < TOTAL; i += 1) {
      var panel = byId('step-' + i);
      if (panel) { panel.className = i === index ? 'step is-on' : 'step'; }
    }
    var steps = document.querySelectorAll('.pstep');
    for (var s = 0; s < steps.length; s += 1) {
      var target = parseInt(steps[s].getAttribute('data-goto'), 10);
      steps[s].className = 'pstep' + (target === index ? ' is-on' : (target < index ? ' is-done' : ''));
    }
    var active = document.querySelector('.pstep.is-on');
    if (active && active.scrollIntoView) { active.scrollIntoView(false); }
    window.scrollTo(0, 0);
    if (index === 9) { refreshPreview(false); }
  }

  function syncCustomVisibility() {
    var selects = document.querySelectorAll('select[id^="f-"]');
    for (var i = 0; i < selects.length; i += 1) {
      var sel = selects[i];
      var custom = byId(sel.id + '-custom');
      if (!custom) { continue; }
      if (sel.value === '__custom__') { custom.hidden = false; }
      else { custom.hidden = true; custom.value = ''; }
    }
    var customRadios = ['f-faction', 'f-moral'];
    for (var r = 0; r < customRadios.length; r += 1) {
      var box = byId(customRadios[r] + '-custom');
      if (!box) { continue; }
      if (radioValue(customRadios[r]) === '__custom__') { box.hidden = false; }
      else { box.hidden = true; box.value = ''; }
    }
  }

  function syncConditionalBlocks() {
    var block = byId('awaken-block');
    if (block) { block.hidden = radioValue('f-awakened') !== '已觉醒'; }
    var relation = byId('f-faction-relation');
    var faction = radioValue('f-faction');
    if (relation) {
      var off = faction === '无所属（独行者）' || faction === '';
      relation.disabled = off;
      if (off) { relation.value = ''; }
    }
  }

  function onFieldChange() {
    syncCustomVisibility();
    syncConditionalBlocks();
    if (manualEdit) {
      previewState.textContent = '预览里有你手改的内容 · 点「刷新预览」';
      return;
    }
    refreshPreview(true);
  }

  function fallbackCopy(text, done) {
    var box = document.createElement('textarea');
    box.value = text;
    box.style.position = 'fixed';
    box.style.left = '-9999px';
    box.style.top = '0';
    document.body.appendChild(box);
    box.focus();
    box.select();
    var ok = false;
    try { ok = document.execCommand('copy'); } catch (error) { ok = false; }
    document.body.removeChild(box);
    if (ok) { done(); return true; }
    preview.focus();
    preview.setSelectionRange(0, preview.value.length);
    return false;
  }

  function copyBlock() {
    var text = preview.value;
    if (!text.replace(/\s/g, '')) {
      toast('资料块还是空的：至少写一个称呼，或者直接滑到你想要的那条开场。', 'err');
      return;
    }
    var succeed = function () {
      toast('资料块已复制。它还没有交给世界——下一步是你亲手把它发出去。', 'ok');
      previewState.textContent = '已复制到剪贴板';
    };
    var failed = function () {
      toast('浏览器拦住了自动复制：已经帮你选中全文，请按 Ctrl+C（手机上长按选择复制）。', 'err');
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(succeed, function () {
        if (!fallbackCopy(text, succeed)) { failed(); }
      });
      return;
    }
    if (!fallbackCopy(text, succeed)) { failed(); }
  }

  function findGoto(node) {
    while (node && node !== document.body) {
      if (node.getAttribute && node.getAttribute('data-goto') !== null) {
        return parseInt(node.getAttribute('data-goto'), 10);
      }
      node = node.parentNode;
    }
    return null;
  }

  document.addEventListener('click', function (event) {
    var goto = findGoto(event.target);
    if (goto !== null && !isNaN(goto)) { showStep(goto); }
  });

  document.addEventListener('input', function (event) {
    if (event.target === preview) {
      manualEdit = true;
      previewState.textContent = '你手改过预览 · 点「刷新预览」才会重新生成';
      return;
    }
    onFieldChange();
  });

  document.addEventListener('change', function (event) {
    if (event.target === preview) { return; }
    onFieldChange();
  });

  var refreshButtons = [byId('btn-refresh'), byId('btn-refresh-2')];
  for (var i = 0; i < refreshButtons.length; i += 1) {
    if (refreshButtons[i]) {
      refreshButtons[i].addEventListener('click', function () {
        refreshPreview(false);
        toast('预览已按表单重新生成。', 'ok');
      });
    }
  }

  var copyButtons = document.querySelectorAll('.copy-trigger');
  for (var c = 0; c < copyButtons.length; c += 1) {
    copyButtons[c].addEventListener('click', copyBlock);
  }

  var toggle = byId('btn-preview-toggle');
  if (toggle) {
    toggle.addEventListener('click', function () {
      var panel = byId('previewPanel');
      var open = panel.className.indexOf('open') >= 0;
      panel.className = open ? 'preview' : 'preview open';
      toggle.setAttribute('aria-expanded', open ? 'false' : 'true');
      toggle.textContent = open ? '资料块预览' : '收起资料块';
    });
  }

  window.addEventListener('beforeunload', function (event) {
    var body = preview.value.split(FOOTER)[0];
    if (!body.replace(BLOCK_TITLE, '').replace(BLOCK_TITLE_AMEND, '').replace(/〔[^〕]*〕/g, '').replace(/\s/g, '')) { return; }
    event.preventDefault();
    event.returnValue = '';
    return '';
  });

  syncCustomVisibility();
  syncConditionalBlocks();
  refreshPreview(false);
})();
</script>
</body>
</html>
